fn determine_food_safety(x: i8, a: i8, b: i8) -> &'static str {
    // Compute how many days have passed since the reference day.
    // We cast to i16 to avoid any potential overflow when subtracting two i8 values.
    let days_past = (b as i16) - (a as i16);

    // Classify according to the rules:
    // - days_past <= 0      => "delicious"
    // - 0 < days_past <= x  => "safe"
    // - days_past > x       => "dangerous"
    if days_past <= 0 {
        "delicious"
    } else if days_past <= x as i16 {
        "safe"
    } else {
        "dangerous"
    }
}

